mapper.update:
UPDATE t_chat_conversation
SET last_msg_id = #{lastMsgId}, last_msg_time = #{lastMsgTime}
WHERE id = #{id}

UPDATE t_chat_member
SET unread_count = unread_count + 1
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND del_flag = '0'

UPDATE t_chat_member
SET unread_count    = 0,
    last_read_msg_id = #{lastReadMsgId}
WHERE conversation_id = #{conversationId}
  AND user_id = #{userId}
  AND del_flag = '0'

UPDATE t_chat_message
SET read_flag = 1, read_time = NOW()
WHERE conversation_id = #{conversationId}
  AND receiver_id = #{receiverId}
  AND read_flag = 0
  AND del_flag = '0'
